def test_ao01_compositional_sort_dedupe():
    def run(items):
        return sorted(set(items))
    assert run([3, 1, 2, 1]) == [1, 2, 3]

def test_ao01_negative_unorderable_rejected():
    try:
        sorted([1, 'x'])
    except TypeError:
        pass
    else:
        raise AssertionError('expected TypeError')

def test_ao01_boundary_empty_and_single():
    assert sorted([]) == []
    assert sorted([1]) == [1]

def test_ao02_compositional_cache_hit():
    store = {}
    def get(k, compute):
        if k not in store:
            store[k] = compute(k)
        return store[k]
    assert get('a', lambda k: len(k)) == 1
    assert get('a', lambda k: 99) == 1

def test_ao02_negative_missing_key_computes():
    store = {}
    def get(k, compute):
        if k not in store:
            store[k] = compute(k)
        return store[k]
    assert get('b', lambda k: 5) == 5
    assert store['b'] == 5

def test_ao02_boundary_zero_capacity_bypass():
    def get(store, cap, k, compute):
        if cap <= 0:
            return compute(k)
        if k not in store:
            store[k] = compute(k)
        return store[k]
    assert get({}, 0, 'a', lambda k: 7) == 7
